.card-sheet { display: grid; grid-template-columns: repeat(auto-fill, 100mm); gap: 4mm; }.label-card { width: 100mm; height: 60mm; padding: 3mm 3.5mm; border: 0.3mm solid rgb(153, 153, 153); border-radius: 1.5mm; display: flex; gap: 3mm; background: rgb(255, 255, 255); color: rgb(21, 25, 29); overflow: hidden; break-inside: avoid; }.label-body { flex: 1 1 0%; min-width: 0px; display: flex; flex-direction: column; }.label-title { flex: 0 0 auto; line-height: 1.15; font-size: 3.6mm; font-weight: 700; letter-spacing: -0.01em; margin-bottom: 1mm; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.label-rows { display: grid; grid-template-columns: max-content 1fr; gap: 0.3mm 2mm; min-height: 0px; overflow: hidden; line-height: 1.25; }.label-key { font-size: 2.1mm; text-transform: uppercase; letter-spacing: 0.04em; color: rgb(107, 117, 125); white-space: nowrap; }.label-val { font-size: 2.5mm; min-width: 0px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.label-qr { flex: 0 0 auto; display: flex; align-items: flex-start; }.label-qr svg { width: 37.2mm; height: auto; display: block; }.label-flag { margin-top: auto; flex: 0 0 auto; line-height: 1.25; font-size: 2.1mm; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: rgb(28, 100, 69); }.label-setup { display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: end; margin-bottom: 14px; }.label-setup label { display: grid; gap: 3px; font-size: 12px; color: var(--color-muted); }.label-setup select, .label-setup input { min-width: 0px; }.label-fields { display: flex; flex-wrap: wrap; gap: 4px 12px; border: 0px; padding: 0px; margin: 0px; }.label-fields legend { font-size: 12px; color: var(--color-muted); margin-bottom: 3px; }.label-setup .label-field { display: flex; align-items: center; gap: 4px; font-size: 13px; color: inherit; }@media print {
  .rail, .topstrip, .page-head, .rail-scrim, .no-print { display: none !important; }
  .shell { display: block !important; height: auto !important; }
  .shell-main, .shell-scroll { overflow: visible !important; height: auto !important; }
  .shell-page, .shell-page-wide { padding: 0px !important; max-width: none !important; }
  body { background: rgb(255, 255, 255) !important; }
  .card-sheet { gap: 3mm; }
  @page { margin: 8mm; }
}
